12	// lowers it, and the value is scoped to the invoice it belongs to.
13	//
14	// The request names no format, but money is shown "properly" everywhere in this app (a dollar sign
15	// and two decimal places, e.g. $265.00 — see money-format.spec.ts), so the remaining is asserted as
16	// that money value. The assertions bind to the VALUE, not to any surrounding label text, by reading
17	// only the invoice-due-amount element and requiring it to contain the correctly-computed figure.
18	// Across the scenarios below (full amount with no payments, amount-minus-payments, and $0.00 when
19	// fully paid) the figure can only be right if it is genuinely "amount after payments" — a value that
20	// merely echoed the gross amount, or the payments total, would be wrong in at least one scenario.
21	//
22	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
23	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId },
24	// `invoices` honours { id, amount, projectId, status } and `payments` honours
25	// { id, invoiceId, amount, date }. This change surfaces no audit records, so there is nothing to
26	// assert on the audit channel.
27	import { test, expect, type Page, type Locator } from '@playwright/test';
28	import { resetAndSeed } from '../support/seed';
29	
30	const paymentRows = (page: Page) => page.locator('[data-testid^="payment-row-"]');
31	
32	// "Still left to pay" shown properly: a dollar sign, the whole-dollar amount and exactly two cents
33	// digits (e.g. $265.00), as every money value in this app is shown. Matched as CONTAINMENT so a
34	// surrounding label ("$265.00 due") does not break the assertion, while the leading "$" keeps the
35	// figure from matching as a substring of a larger number ("$2,650.00"). All amounts seeded below
36	// stay under a thousand, so thousands grouping never arises.
37	const due = (dollars: number): RegExp => new RegExp(`\\$${dollars}\\.00`);
