import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

// One invoice's money breakdown, worked out on the server (see InvoiceSummaryGetLogic): its subtotal
// (the sum of its line items), the percentage discount taken off it, that discount in money, and the
// final total (subtotal minus the discount). Keyed under the shared ['invoices'] prefix so adding or
// removing a line — which invalidates ['invoices'] — also refreshes the breakdown, with no import
// between the two.
export type InvoiceSummary = {
  invoiceId: number;
  subtotal: number;
  discountPct: number;
  discount: number;
  total: number;
};

export const invoiceSummaryKey = (invoiceId: number) =>
  ['invoices', 'summary', invoiceId] as const;

export function useInvoiceSummary(invoiceId: number) {
  return useQuery({
    queryKey: invoiceSummaryKey(invoiceId),
    queryFn: () => getJson<InvoiceSummary>(`/api/invoices/summary?invoiceId=${invoiceId}`),
  });
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

// How much is still left to pay on one invoice: its amount minus everything paid against it, worked
// out on the server (see InvoiceDueGetLogic). Keyed under the shared ['invoices'] prefix so that
// recording a payment — which invalidates ['invoices'] (see useAddPayment) — also refreshes the
// amount due, with no import between the two.
export type InvoiceDue = {
  invoiceId: number;
  amount: number;
  paid: number;
  due: number;
  // Worked out from the payments on the server (SENT / PARTIAL / PAID), not a hand-set flag.
  status: string;
};

export const invoiceDueKey = (invoiceId: number) => ['invoices', 'due', invoiceId] as const;

export function useInvoiceDue(invoiceId: number) {
  return useQuery({
    queryKey: invoiceDueKey(invoiceId),
    queryFn: () => getJson<InvoiceDue>(`/api/invoices/due?invoiceId=${invoiceId}`),
  });
}
import { InvoiceRow } from '../../slots/defs/invoiceRow';
import { formatMoney } from '../../ui/money';
import type { Invoice } from './invoices';
import { useInvoiceDue } from './invoiceDue';

// "How much is still left to pay on this invoice" — a self-contained cell filling the invoice-row
// region. The table is not edited to add it beyond rendering the region (CLAUDE.md rule 3); it reads
// the server-derived amount due (invoice amount minus its payments) for its own invoice. Sharing the
// ['invoices'] query key, it drops on its own when a payment is recorded — no parent hands it data.
function DueAmount({ invoice }: { invoice: Invoice }) {
  const { data } = useInvoiceDue(invoice.id);
  return (
    <span data-testid="invoice-due-amount">{data ? formatMoney(data.due) : ''}</span>
  );
}

export const contribution = InvoiceRow.fill({ order: 10, Component: DueAmount });
import { InvoiceDetail } from '../../slots/defs/invoiceDetail';
import { formatMoney } from '../../ui/money';
import { useInvoiceSummary } from './invoiceSummary';

// The money breakdown panel on the invoice detail page — its own file, filling the shared
// invoice.detail region (CLAUDE.md rule 3). It reads the server-worked-out summary for its own
// invoice and shows the subtotal (the sum of the lines), the discount taken off it, and the final
// total. Sharing the ['invoices'] query key, it stays in step with the line items: adding a line
// re-reads it. The final total is the invoice's amount, shown under the line items table as
// `invoice-amount`; this panel surfaces the two figures that make it up.
function InvoiceSummary({ invoiceId }: { invoiceId: number }) {
  const { data: summary } = useInvoiceSummary(invoiceId);

  if (!summary) {
    return null;
  }

  return (
    <section data-testid="invoice-summary">
      <h2>Summary</h2>
      <dl>
        <dt>Subtotal</dt>
        <dd data-testid="invoice-subtotal">{formatMoney(summary.subtotal)}</dd>
        <dt>Discount ({Number(summary.discountPct)}%)</dt>
        <dd data-testid="invoice-discount">{formatMoney(summary.discount)}</dd>
        <dt>Total</dt>
        <dd data-testid="invoice-total">{formatMoney(summary.total)}</dd>
      </dl>
    </section>
  );
}

export const contribution = InvoiceDetail.fill({ order: 20, Component: InvoiceSummary });
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';

// An invoice raised on a project. Everything that shows a project's invoices shares the key
// ['invoices', projectId]; invalidating it after a write refreshes the list and its total together.
export type Invoice = {
  id: number;
  projectId: number;
  amount: number;
  status: string;
  issuedDate: string;
  dueDate: string;
};

export const invoicesKey = (projectId: number) => ['invoices', projectId] as const;

// How a project's invoices are ordered. 'due' asks the server for earliest due date first; any other
// value keeps the default id order. The sort is part of the query key (as a suffix under the shared
// ['invoices', projectId] prefix) so each ordering caches on its own, while a write still invalidates
// the whole prefix and refreshes every ordering at once.
export function useInvoices(projectId: number, sort: string = 'id') {
  return useQuery({
    queryKey: [...invoicesKey(projectId), sort],
    queryFn: () => getJson<Invoice[]>(`/api/invoices?projectId=${projectId}&sort=${sort}`),
  });
}

export function useCreateInvoice(projectId: number) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: { amount: number }) =>
      postJson<Invoice>('/api/invoices', { projectId, amount: input.amount }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: invoicesKey(projectId) }),
  });
}

// Send a draft invoice: POSTs {id} and invalidates ['invoices', projectId] so the list reflects the
// new SENT status from the server. Sending is what records the audit entry and unlocks payment.
export function useSendInvoice(projectId: number) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: { id: number }) =>
      postJson<Invoice>('/api/invoices/send', { id: input.id }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: invoicesKey(projectId) }),
  });
}

