package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.math.RoundingMode;
import org.springframework.web.bind.annotation.RequestParam;
import net.officefloor.web.ObjectResponse;

/**
 * {@code GET /api/invoices/summary?invoiceId=<id>} — the money breakdown for one invoice: its
 * subtotal (the worked-out sum of its line items, Flyway V13/V14, kept in the amount column), the
 * percentage discount taken off it (Flyway V27), the discount in money, and the final total
 * (subtotal minus discount). The figures are worked out on the server so the money math lives in one
 * place; an invoice with no discount simply bills its full subtotal. Wired by
 * {@code officefloor/rest/api/invoices/summary.GET.yml}.
 */
public class InvoiceSummaryGetLogic {

    public void service(@RequestParam("invoiceId") Long invoiceId, InvoiceRepository invoices,
            ObjectResponse<InvoiceSummaryView> response) {
        Invoice invoice = invoices.findById(invoiceId).orElse(null);
        BigDecimal subtotal = invoice != null ? invoice.getAmount() : BigDecimal.ZERO;
        BigDecimal discountPct = invoice != null && invoice.getDiscountPct() != null
                ? invoice.getDiscountPct()
                : BigDecimal.ZERO;
        // Discount in money, rounded to whole cents; the final total is the subtotal less that.
        BigDecimal discount = subtotal.multiply(discountPct)
                .divide(BigDecimal.valueOf(100))
                .setScale(2, RoundingMode.HALF_UP);
        BigDecimal total = subtotal.subtract(discount);
        response.send(new InvoiceSummaryView(invoiceId, subtotal, discountPct, discount, total));
    }

    /** One invoice's money breakdown: subtotal, the discount percentage, the discount, the total. */
    public static class InvoiceSummaryView {
        private final long invoiceId;
        private final BigDecimal subtotal;
        private final BigDecimal discountPct;
        private final BigDecimal discount;
        private final BigDecimal total;

        public InvoiceSummaryView(long invoiceId, BigDecimal subtotal, BigDecimal discountPct,
                BigDecimal discount, BigDecimal total) {
            this.invoiceId = invoiceId;
            this.subtotal = subtotal;
            this.discountPct = discountPct;
            this.discount = discount;
            this.total = total;
        }

        public long getInvoiceId() {
            return invoiceId;
        }

        public BigDecimal getSubtotal() {
            return subtotal;
        }

        public BigDecimal getDiscountPct() {
            return discountPct;
        }

        public BigDecimal getDiscount() {
            return discount;
        }

        public BigDecimal getTotal() {
            return total;
        }
    }
}
package net.officefloor.hq.app;

import java.math.BigDecimal;
import org.springframework.web.bind.annotation.RequestParam;
import net.officefloor.web.ObjectResponse;

/**
 * {@code GET /api/invoices/due?invoiceId=<id>} — how much is still left to pay on one invoice: its
 * amount (the worked-out sum of its line items, Flyway V13/V14) minus everything paid against it (the
 * sum of its payments, Flyway V19). The figure is derived on the server so the money math lives in
 * one place, and an invoice with no payments yet is simply its full amount. Wired by
 * {@code officefloor/rest/api/invoices/due.GET.yml}.
 */
public class InvoiceDueGetLogic {

    public void service(@RequestParam("invoiceId") Long invoiceId, InvoiceRepository invoices,
            PaymentRepository payments, ObjectResponse<InvoiceDueView> response) {
        Invoice invoice = invoices.findById(invoiceId).orElse(null);
        BigDecimal amount = invoice != null ? invoice.getAmount() : BigDecimal.ZERO;
        BigDecimal paid = payments.findByInvoiceIdOrderByIdAsc(invoiceId).stream()
                .map(Payment::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        // The status is worked out from the payments too (see InvoiceStatus), so the detail page
        // reads the same one-place rule as the list — no hand-set paid flag.
        String status = InvoiceStatus.derive(invoice != null ? invoice.getStatus() : null, amount,
                paid);
        response.send(new InvoiceDueView(invoiceId, amount, paid, amount.subtract(paid), status));
    }

    /**
     * What is left to pay on one invoice: its amount, what has been paid, the difference, and the
     * status worked out from the payments (SENT / PARTIAL / PAID).
     */
    public static class InvoiceDueView {
        private final long invoiceId;
        private final BigDecimal amount;
        private final BigDecimal paid;
        private final BigDecimal due;
        private final String status;

        public InvoiceDueView(long invoiceId, BigDecimal amount, BigDecimal paid, BigDecimal due,
                String status) {
            this.invoiceId = invoiceId;
            this.amount = amount;
            this.paid = paid;
            this.due = due;
            this.status = status;
        }

        public long getInvoiceId() {
            return invoiceId;
        }

        public BigDecimal getAmount() {
            return amount;
        }

        public BigDecimal getPaid() {
            return paid;
        }

        public BigDecimal getDue() {
            return due;
        }

        public String getStatus() {
            return status;
        }
    }
}
package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.util.Comparator;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import org.springframework.web.bind.annotation.RequestParam;
import net.officefloor.web.ObjectResponse;

/**
 * {@code GET /api/clients/statement?clientId=<id>} — a client's statement: every invoice across ALL
 * of that client's projects gathered in one place, each carrying how much is still due on it (its
 * amount minus what has been paid against it — the same money rule as {@link InvoiceDueGetLogic}),
 * and the OUTSTANDING TOTAL the client still owes (the sum of those dues). Derived on the server so
 * the money math lives in one place. Wired by {@code officefloor/rest/api/clients/statement.GET.yml}.
 */
public class ClientStatementGetLogic {

    public void service(@RequestParam("clientId") Long clientId, ProjectRepository projects,
            InvoiceRepository invoices, PaymentRepository payments,
            ObjectResponse<ClientStatementView> response) {
        // The client's projects are the ones its invoices hang off (invoice -> project -> client).
        Set<Long> projectIds = projects.findAll().stream()
                .filter(p -> clientId.equals(p.getClientId()))
                .map(Project::getId)
                .collect(Collectors.toSet());
        List<StatementInvoiceView> rows = invoices.findAll().stream()
                .filter(i -> projectIds.contains(i.getProjectId()))
                .sorted(Comparator.comparing(Invoice::getId))
                .map(i -> {
                    BigDecimal paid = payments.findByInvoiceIdOrderByIdAsc(i.getId()).stream()
                            .map(Payment::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
                    BigDecimal due = i.getAmount().subtract(paid);
                    String status = InvoiceStatus.derive(i.getStatus(), i.getAmount(), paid);
                    return new StatementInvoiceView(i.getId(), i.getProjectId(), i.getAmount(),
                            paid, due, status);
                })
                .collect(Collectors.toList());
        BigDecimal outstanding = rows.stream().map(StatementInvoiceView::getDue)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        response.send(new ClientStatementView(clientId, rows, outstanding));
    }

    /** A client's statement: its invoices, each with its due, and the total still owed across them. */
    public static class ClientStatementView {
        private final long clientId;
        private final List<StatementInvoiceView> invoices;
        private final BigDecimal outstandingTotal;

        public ClientStatementView(long clientId, List<StatementInvoiceView> invoices,
                BigDecimal outstandingTotal) {
            this.clientId = clientId;
            this.invoices = invoices;
            this.outstandingTotal = outstandingTotal;
        }

        public long getClientId() {
            return clientId;
        }

        public List<StatementInvoiceView> getInvoices() {
            return invoices;
        }

        public BigDecimal getOutstandingTotal() {
            return outstandingTotal;
        }
    }

    /** One invoice on the statement: its amount, what has been paid, what is still due, and status. */
    public static class StatementInvoiceView {
        private final long id;
        private final long projectId;
        private final BigDecimal amount;
        private final BigDecimal paid;
        private final BigDecimal due;
        private final String status;

        public StatementInvoiceView(long id, long projectId, BigDecimal amount, BigDecimal paid,
                BigDecimal due, String status) {
            this.id = id;
            this.projectId = projectId;
            this.amount = amount;
            this.paid = paid;
            this.due = due;
            this.status = status;
        }

        public long getId() {
            return id;
        }

        public long getProjectId() {
            return projectId;
        }

        public BigDecimal getAmount() {
            return amount;
        }

        public BigDecimal getPaid() {
            return paid;
        }

        public BigDecimal getDue() {
            return due;
        }

        public String getStatus() {
            return status;
        }
    }
}
