import { test, expect } from '@playwright/test';
import { resetAndSeed } from '../support/seed';

test('probe where invoice-due-amount renders', async ({ page }) => {
  await resetAndSeed({
    clients: [{ id: 1, name: 'Acme', email: 'a@a.test' }],
    projects: [{ id: 1, name: 'Web', clientId: 1 }],
    invoices: [{ id: 1, amount: 500, projectId: 1, status: 'SENT', discountPct: 10 }],
    payments: [{ id: 1, invoiceId: 1, amount: 100, date: '2021-03-14' }],
  });

  await page.goto('/projects/1');
  await expect(page.getByTestId('project-detail-page')).toBeVisible();
  const onProject = await page.getByTestId('invoice-due-amount').count();
  const rowDue = await page
    .getByTestId('invoice-row-1')
    .getByTestId('invoice-due-amount')
    .textContent()
    .catch(() => '(none)');
  console.log('PROBE project-page invoice-due-amount count=', onProject, 'row1 due text=', rowDue);

  await page.goto('/invoices/1');
  await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
  const onDetail = await page.getByTestId('invoice-due-amount').count();
  const total = await page.getByTestId('invoice-total').textContent().catch(() => '(none)');
  console.log('PROBE invoice-detail invoice-due-amount count=', onDetail, 'invoice-total=', total);
});

